  /* ——— N28 · totals, average, the largest ——— */
  C.level({
    id: 'N28', chapter: 4, num: 28, title: 'Totaliser', summary: 'somme · moyenne · le plus grand · array_sum', notions: ['totaliser'],
    lessons: {
      somme: {
        title: 'Le total et la moyenne',
        html: `<p>Pour additionner les cases, on prépare un total à 0 <b>avant</b> la boucle, et chaque tour y ajoute une case :</p>
<div class="rule">$total = 0;<br><span class="kw">foreach</span> ($notes <span class="kw">as</span> $n) {<br>    $total = $total + $n;<br>}</div>
<p>Si <code>$total = 0;</code> est écrit <b>dans</b> la boucle, le total repart de zéro à chaque tour : il ne reste que la dernière case.</p>
<p>La <b>moyenne</b>, c'est le total divisé par le nombre de cases : <code>$total / count($notes)</code>. PHP sait aussi faire le total tout seul : <code>array_sum($notes)</code>.</p>
<p>Le piège : <b>une liste vide</b>. <code>count</code> vaut alors 0, et diviser par 0 arrête le programme. On teste avant de diviser : <code>if (count($notes) == 0)</code>.</p>`,
        example: '$total = 0;\nforeach ($notes as $n) {\n    $total = $total + $n;\n}\necho "Total : " . $total . "\\n";\necho "Avec array_sum : " . array_sum($notes) . "\\n";\necho "Moyenne : " . round($total / count($notes), 1);',
        vars: { notes: [12, 8, 15, 10] },
        tryit: 'Déplace $total = 0; dans la boucle : que devient le total ?'
      },
      max: {
        title: 'Le plus grand',
        html: `<p>Pour trouver la plus grande valeur, on garde dans <code>$max</code> la plus grande vue jusqu'ici, et on la remplace dès qu'une case la dépasse :</p>
<div class="rule">$max = $notes[0];<br><span class="kw">foreach</span> ($notes <span class="kw">as</span> $n) {<br>    <span class="kw">if</span> ($n &gt; $max) {<br>        $max = $n;<br>    }<br>}</div>
<p><b>On part de la première case</b>, pas de 0. Avec des températures de -3, -8 et -1, aucune ne dépasse 0 : un <code>$max = 0</code> resterait à 0, une valeur qui n'est même pas dans la liste.</p>
<p>Pour le plus petit, même chose avec <code>&lt;</code>. Une liste vide n'a pas de case 0 : si elle peut être vide, teste-la d'abord.</p>`,
        example: '$max = $temperatures[0];\nforeach ($temperatures as $t) {\n    if ($t > $max) {\n        $max = $t;\n    }\n}\necho $max;',
        vars: { temperatures: [-3, -8, -1, -5] },
        tryit: 'Remplace $max = $temperatures[0]; par $max = 0; et compare.'
      }
    },
    steps: {
      predire: { before: 'somme', kind: 'choose', ask: 'Sans l\'exécuter : qu\'affiche ce programme ?', code: 'foreach ($notes as $n) {\n    $total = 0;\n    $total = $total + $n;\n}\necho $total;', vars: { notes: [4, 7, 2] }, options: ['2', '13', '0', '4'], hints: ['Regarde où est écrit $total = 0; : il est exécuté à chaque tour, juste avant l\'addition.'] },
      suivre: { kind: 'trace', ask: 'Remplis le tableau de suivi : que valent $n et $max à la fin de chaque tour ?', code: '$max = $notes[0];\nforeach ($notes as $n) {\n    if ($n > $max) {\n        $max = $n;\n    }\n}\necho $max;', vars: { notes: [11, 15, 9, 17, 13] }, after: 5, watch: ['$n', '$max'], hints: ['$max part de la première note, 11. Il ne change que lorsqu\'une note le dépasse.'] },
      comprendre: {},
      completer: { kind: 'complete', ask: 'Affiche la moyenne des notes, arrondie à une décimale. S\'il n\'y a aucune note, affiche « Aucune note ».', template: 'if (count($notes) [[]] 0) {\n    echo "Aucune note";\n} else {\n    echo round([[]]($notes) / [[]]($notes), 1);\n}', fill: ['==', 'array_sum', 'count'], words: ['==', '=', '>', 'array_sum', 'count', 'max'], ref: 'if (count($notes) == 0) {\n    echo "Aucune note";\n} else {\n    echo round(array_sum($notes) / count($notes), 1);\n}', vars: { notes: [12, 8, 15, 10] }, hidden: [{ vars: { notes: [] }, label: 'aucune note' }, { vars: { notes: [14] }, label: 'une seule note' }, { vars: { notes: [9, 10] } }], hints: ['On teste d\'abord la liste vide. La moyenne, c\'est le total divisé par le nombre de notes.', 'if (count($notes) == 0) {\n    …\n} else {\n    echo round(array_sum($notes) / …($notes), 1);\n}'] },
      reparer: { before: 'max', kind: 'repair', ask: 'Ce programme doit afficher la plus haute température relevée dans la réserve des fossiles. Il se trompe les semaines où il gèle tous les jours : répare-le.', starter: '$max = 0;\nforeach ($temperatures as $t) {\n    if ($t > $max) {\n        $max = $t;\n    }\n}\necho $max;', ref: '$max = $temperatures[0];\nforeach ($temperatures as $t) {\n    if ($t > $max) {\n        $max = $t;\n    }\n}\necho $max;', vars: { temperatures: [4, 7, 2, 5] }, hidden: [{ vars: { temperatures: [-3, -8, -1] }, label: 'il gèle toute la semaine' }, { vars: { temperatures: [-6] }, label: 'un seul relevé, négatif' }, { vars: { temperatures: [0, -2, 3, 1, 6] } }], traps: ['$max = $temperatures[0];\nfor ($i = 1; $i < 4; $i++) {\n    if ($temperatures[$i] > $max) {\n        $max = $temperatures[$i];\n    }\n}\necho $max;'], ir: [{ re: /\$max\s*=\s*0\s*;/, text: 'Si toutes les valeurs sont négatives, aucune ne dépasse 0 : <code>$max</code> reste à 0, une valeur qui n\'est même pas dans la liste. Pars de la première case : <code>$max = $temperatures[0];</code>' }], hints: ['Essaie dans ta tête avec -3, -8 et -1 : laquelle dépasse 0 ? Le départ doit être une vraie valeur de la liste.', '$max = $temperatures[0];\nforeach ($temperatures as $t) {\n    …\n}'] },
      ecrire1: { kind: 'write', ask: 'La liste $effectifs donne le nombre de spécimens de chaque salle. Affiche le total, puis le nombre moyen de spécimens par salle arrondi à l\'unité, une valeur par ligne. S\'il n\'y a aucune salle, affiche seulement « Aucune salle ».', ref: 'if (count($effectifs) == 0) {\n    echo "Aucune salle";\n} else {\n    $total = array_sum($effectifs);\n    echo $total . "\\n";\n    echo round($total / count($effectifs));\n}', vars: { effectifs: [12, 30, 7, 21] }, hidden: [{ vars: { effectifs: [] }, label: 'aucune salle' }, { vars: { effectifs: [9] }, label: 'une seule salle' }, { vars: { effectifs: [40, 0, 5] } }], traps: ['$total = array_sum($effectifs);\necho $total . "\\n";\necho round($total / count($effectifs));'], ir: [{ re: /^(?![\s\S]*count\s*\(\s*\$effectifs\s*\)\s*(==|<|<=|>|!=)\s*0)/, text: 'Une liste vide a 0 case : diviser par <code>count($effectifs)</code> arrête alors le programme. Teste <code>count($effectifs) == 0</code> avant.' }], hints: ['D\'abord le test de la liste vide ; sinon le total, puis le total divisé par le nombre de salles.', 'if (count($effectifs) == 0) {\n    echo "Aucune salle";\n} else {\n    $total = …;\n    echo $total . "\\n";\n    echo round(…);\n}'] },
      ecrire2: { kind: 'write', ask: 'Affiche la valeur, en euros, du spécimen le moins cher de la liste $valeurs.', ref: '$min = $valeurs[0];\nforeach ($valeurs as $v) {\n    if ($v < $min) {\n        $min = $v;\n    }\n}\necho $min;', vars: { valeurs: [450, 120, 800, 300] }, hidden: [{ vars: { valeurs: [1500, 2400, 1800] }, label: 'tous valent plus de 1000 €' }, { vars: { valeurs: [75] }, label: 'un seul spécimen' }, { vars: { valeurs: [300, 90, 90] }, label: 'deux minimums ex æquo' }], traps: ['$min = 1000;\nforeach ($valeurs as $v) {\n    if ($v < $min) {\n        $min = $v;\n    }\n}\necho $min;'], ir: [{ re: /\$min\s*=\s*\d+\s*;/, text: 'Un nombre « assez grand » au départ finit toujours par être trop petit : pars de la première case, <code>$min = $valeurs[0];</code>' }], hints: ['Comme le plus grand, avec < : on part de la première case et on garde la plus petite vue jusqu\'ici.', '$min = $valeurs[0];\nforeach ($valeurs as $v) {\n    if ($v < $min) {\n        …\n    }\n}\necho $min;'] },
      ecrire3: { kind: 'write', ask: 'Affiche la plus haute température de la liste, puis le nombre de jours où elle a été relevée, une valeur par ligne.', ref: '$max = $temperatures[0];\nforeach ($temperatures as $t) {\n    if ($t > $max) {\n        $max = $t;\n    }\n}\n$jours = 0;\nforeach ($temperatures as $t) {\n    if ($t == $max) {\n        $jours++;\n    }\n}\necho $max . "\\n";\necho $jours;', vars: { temperatures: [6, 9, 4, 9, 7] }, hidden: [{ vars: { temperatures: [-4, -2, -7, -2] }, label: 'il gèle tous les jours, deux jours à -2' }, { vars: { temperatures: [3] }, label: 'un seul relevé' }, { vars: { temperatures: [5, 8, 2] } }], traps: ['$max = 0;\nforeach ($temperatures as $t) {\n    if ($t > $max) {\n        $max = $t;\n    }\n}\n$jours = 0;\nforeach ($temperatures as $t) {\n    if ($t == $max) {\n        $jours++;\n    }\n}\necho $max . "\\n";\necho $jours;'], ir: [{ re: /\$max\s*=\s*0\s*;/, text: 'Avec des températures toutes négatives, <code>$max = 0</code> ne bouge jamais : pars de <code>$temperatures[0]</code>.' }], hints: ['Deux boucles : la première trouve le maximum, la seconde compte les jours qui lui sont égaux.', '$max = $temperatures[0];\nforeach (…) {\n    …\n}\n$jours = 0;\nforeach ($temperatures as $t) {\n    if ($t == $max) {\n        $jours++;\n    }\n}\n…'] },
      rappel1: { kind: 'recall' },
      rappel2: { kind: 'recall' }
    }
  });

  /* ——— N29 · filtering into a new list ——— */
  C.level({
    id: 'N29', chapter: 4, num: 29, title: 'Filtrer dans un nouveau tableau', summary: '$res = [] · if · $res[] = · implode', notions: ['filtrer'],
    lessons: {
      filtrer: {
        title: 'Garder certaines cases',
        html: `<p>Pour garder seulement certaines valeurs, on construit une <b>nouvelle liste</b> : vide avant la boucle, et chaque valeur qui passe le test y est ajoutée.</p>
<div class="rule">$admis = [];<br><span class="kw">foreach</span> ($notes <span class="kw">as</span> $n) {<br>    <span class="kw">if</span> ($n &gt;= 10) {<br>        $admis[] = $n;<br>    }<br>}<br><span class="kw">echo</span> count($admis);</div>
<p>Après la boucle, <code>$admis</code> contient les notes d'au moins 10, dans l'ordre, et <code>count($admis)</code> dit combien il y en a.</p>
<p>Le piège : <code>$admis = [];</code> écrit <b>dans</b> la boucle vide la liste à chaque tour. Il ne reste au mieux que la dernière valeur.</p>`,
        example: '$admis = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        $admis[] = $n;\n    }\n}\necho count($admis) . " admis\\n";\nforeach ($admis as $a) {\n    echo $a . "\\n";\n}',
        vars: { notes: [14, 8, 10, 6, 17] },
        tryit: 'Garde plutôt les notes sous 10 : change seulement la condition.'
      },
      implode: {
        title: 'Afficher une liste : implode',
        html: `<p><code>implode(", ", $liste)</code> colle toutes les valeurs d'une liste en <b>un seul texte</b>, avec <code>", "</code> entre elles :</p>
<div class="rule"><span class="kw">echo</span> implode(", ", ['Léa', 'Tom', 'Inès']);  <span class="c">// Léa, Tom, Inès</span></div>
<p>Le séparateur ne se met qu'<b>entre</b> les valeurs : rien au début, rien à la fin. Pour une valeur par ligne, on garde une boucle avec <code>"\\n"</code>.</p>
<p>Une liste vide donne un texte vide : rien ne s'affiche. Si la consigne demande un message (« Personne »), teste <code>count($liste) == 0</code> avant.</p>`,
        example: '$liste = [\'Léa\', \'Tom\', \'Inès\'];\necho implode(", ", $liste) . "\\n";\necho implode(" / ", $liste);',
        tryit: 'Vide la liste ($liste = [];) : que s\'affiche-t-il ?'
      }
    },
    steps: {
      predire: { before: 'filtrer', kind: 'choose', ask: 'Sans l\'exécuter : qu\'affiche ce programme ?', code: '$res = [];\nforeach ([12, 7, 15, 9] as $n) {\n    if ($n >= 10) {\n        $res[] = $n;\n    }\n}\necho count($res);', options: ['2', '4', '27', '1'], hints: ['Seules les valeurs d\'au moins 10 sont ajoutées à $res : combien y en a-t-il ?'] },
      suivre: { kind: 'trace', ask: 'Remplis le tableau de suivi : que valent $n et $admis à la fin de chaque tour ?', code: '$admis = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        $admis[] = $n;\n    }\n}', vars: { notes: [14, 8, 10, 6] }, after: 5, watch: ['$n', '$admis'], hints: ['La liste ne grandit qu\'aux tours où la note est d\'au moins 10 ; aux autres tours, elle ne change pas.'] },
      comprendre: {},
      completer: { kind: 'complete', ask: 'Construis la liste $chers des valeurs de plus de 1000 €, puis affiche combien il y en a.', template: '$chers = [[]];\nforeach ($valeurs as $v) {\n    if ($v [[]] 1000) {\n        [[]] = $v;\n    }\n}\necho count($chers);', fill: ['[]', '>', '$chers[]'], words: ['[]', '0', '>', '>=', '$chers[]', '$chers', '$v'], ref: '$chers = [];\nforeach ($valeurs as $v) {\n    if ($v > 1000) {\n        $chers[] = $v;\n    }\n}\necho count($chers);', vars: { valeurs: [800, 2500, 1200, 400] }, hidden: [{ vars: { valeurs: [1000, 300] }, label: 'une valeur pile à 1000 € (pas plus de 1000)' }, { vars: { valeurs: [5000] }, label: 'un seul spécimen' }], hints: ['Une liste vide au départ ; dans le if, on ajoute la valeur à la fin de la liste.', '$chers = [];\nforeach ($valeurs as $v) {\n    if ($v > 1000) {\n        $chers[] = …;\n    }\n}'] },
      reparer: { before: 'implode', kind: 'repair', ask: 'Ce programme doit afficher, séparés par « , », les prénoms des élèves qui ont au moins une absence ($prenoms et $absences sont rangés dans le même ordre), ou « Personne ». Il n\'en affiche qu\'un : répare-le.', starter: 'for ($i = 0; $i < count($prenoms); $i++) {\n    $absents = [];\n    if ($absences[$i] > 0) {\n        $absents[] = $prenoms[$i];\n    }\n}\nif (count($absents) == 0) {\n    echo "Personne";\n} else {\n    echo implode(", ", $absents);\n}', ref: '$absents = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($absences[$i] > 0) {\n        $absents[] = $prenoms[$i];\n    }\n}\nif (count($absents) == 0) {\n    echo "Personne";\n} else {\n    echo implode(", ", $absents);\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], absences: [0, 2, 0, 3] }, hidden: [{ vars: { absences: [0, 1, 4, 0] }, label: 'Tom n\'a qu\'une absence, Zoé aucune' }, { vars: { absences: [0, 0, 0, 0] }, label: 'aucune absence' }, { vars: { prenoms: ['Hugo'], absences: [5] }, label: 'un seul élève' }], traps: ['$absents = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($absences[$i] > 1) {\n        $absents[] = $prenoms[$i];\n    }\n}\nif (count($absents) == 0) {\n    echo "Personne";\n} else {\n    echo implode(", ", $absents);\n}'], ir: [{ re: /for\s*\([^)]*\)\s*\{\s*\$absents\s*=\s*\[\s*\]/, text: '<code>$absents = [];</code> dans la boucle vide la liste à chaque tour : seul le dernier tour compte. Prépare-la une fois, avant la boucle.' }, { re: /\$absences\s*\[\s*\$i\s*\]\s*>\s*1/, text: '« Au moins une absence », c\'est <code>&gt; 0</code> (ou <code>&gt;= 1</code>).' }], hints: ['Ouvre « Pas à pas » et regarde $absents au début de chaque tour : que lui arrive-t-il ?', '$absents = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if (…) {\n        $absents[] = $prenoms[$i];\n    }\n}\n…'] },
      ecrire1: { kind: 'write', ask: 'Construis la liste des notes strictement inférieures à 10, puis affiche-la sur une ligne, les notes séparées par « , ». S\'il n\'y en a aucune, affiche « Aucune ».', ref: '$basses = [];\nforeach ($notes as $n) {\n    if ($n < 10) {\n        $basses[] = $n;\n    }\n}\nif (count($basses) == 0) {\n    echo "Aucune";\n} else {\n    echo implode(", ", $basses);\n}', vars: { notes: [12, 7, 15, 4, 9] }, hidden: [{ vars: { notes: [10, 8, 10] }, label: 'des notes pile à 10' }, { vars: { notes: [11, 16] }, label: 'aucune note sous 10' }], traps: ['$basses = [];\nforeach ($notes as $n) {\n    if ($n <= 10) {\n        $basses[] = $n;\n    }\n}\nif (count($basses) == 0) {\n    echo "Aucune";\n} else {\n    echo implode(", ", $basses);\n}', '$basses = [];\nforeach ($notes as $n) {\n    if ($n < 10) {\n        $basses[] = $n;\n    }\n}\necho implode(", ", $basses);'], hints: ['Une liste vide, une boucle qui ajoute les notes sous 10 ; à la fin, un if sur count pour choisir entre « Aucune » et implode.', '$basses = [];\nforeach ($notes as $n) {\n    if ($n < 10) {\n        …\n    }\n}\nif (count($basses) == 0) {\n    echo "Aucune";\n} else {\n    echo implode(", ", …);\n}'] },
      ecrire2: { kind: 'write', ask: '$noms et $annees sont rangés dans le même ordre : $annees[$i] est l\'année d\'entrée du spécimen $noms[$i]. Affiche, un par ligne, les spécimens entrés avant 1900.', ref: 'for ($i = 0; $i < count($noms); $i++) {\n    if ($annees[$i] < 1900) {\n        echo $noms[$i] . "\\n";\n    }\n}', vars: { noms: ['Trilobite', 'Ammonite', 'Mammouth', 'Dodo'], annees: [1911, 1854, 1952, 1872] }, hidden: [{ vars: { noms: ['Silex', 'Quartz'], annees: [1900, 1899] }, label: 'une entrée pile en 1900' }, { vars: { noms: ['Loup gris', 'Ours brun', 'Grand pingouin', 'Archéoptéryx', 'Améthyste'], annees: [1840, 2004, 1844, 1877, 1890] }, label: 'cinq spécimens' }], traps: ['for ($i = 0; $i < 4; $i++) {\n    if ($annees[$i] < 1900) {\n        echo $noms[$i] . "\\n";\n    }\n}', 'for ($i = 0; $i < count($noms); $i++) {\n    if ($annees[$i] <= 1900) {\n        echo $noms[$i] . "\\n";\n    }\n}'], hints: ['Il faut le même numéro de case dans les deux listes : une boucle for, et $annees[$i] avec $noms[$i].', 'for ($i = 0; $i < count($noms); $i++) {\n    if ($annees[$i] < 1900) {\n        echo … . "\\n";\n    }\n}'] },
      ecrire3: { kind: 'write', ask: 'Sépare les notes en deux listes, les réussites (au moins 10) et les échecs. Affiche « Réussites : 12, 15 » sur une ligne, puis « Échecs : 8, 6 » sur la suivante (rien après les deux-points si la liste est vide).', ref: '$reussites = [];\n$echecs = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        $reussites[] = $n;\n    } else {\n        $echecs[] = $n;\n    }\n}\necho "Réussites : " . implode(", ", $reussites) . "\\n";\necho "Échecs : " . implode(", ", $echecs);', vars: { notes: [12, 8, 15, 6] }, hidden: [{ vars: { notes: [10, 9] }, label: 'une note pile à 10' }, { vars: { notes: [14, 11] }, label: 'aucun échec' }, { vars: { notes: [] }, label: 'aucune note' }], traps: ['$reussites = [];\n$echecs = [];\nforeach ($notes as $n) {\n    if ($n > 10) {\n        $reussites[] = $n;\n    } else {\n        $echecs[] = $n;\n    }\n}\necho "Réussites : " . implode(", ", $reussites) . "\\n";\necho "Échecs : " . implode(", ", $echecs);'], hints: ['Deux listes vides avant la boucle ; un if / else qui range chaque note dans l\'une ou l\'autre.', '$reussites = [];\n$echecs = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        …\n    } else {\n        …\n    }\n}\necho "Réussites : " . implode(", ", $reussites) . "\\n";\n…'] },
      rappel1: { kind: 'recall' },
      rappel2: { kind: 'recall' }
    }
  });

  /* ——— N30 · searching ——— */
  C.level({
    id: 'N30', chapter: 4, num: 30, title: 'Chercher', summary: 'drapeau · le premier qui… · in_array · array_search', notions: ['chercher-tab'],
    lessons: {
      drapeau: {
        title: 'Chercher avec une boucle : le drapeau',
        html: `<p>Pour savoir si une valeur est dans la liste, on lève un <b>drapeau</b> : une variable à <code>false</code> avant la boucle, mise à <code>true</code> dès qu'on trouve.</p>
<div class="rule">$trouve = <span class="kw">false</span>;<br><span class="kw">foreach</span> ($prenoms <span class="kw">as</span> $p) {<br>    <span class="kw">if</span> ($p == $cherche) {<br>        $trouve = <span class="kw">true</span>;<br>    }<br>}</div>
<p><b>Jamais de <code>else { $trouve = false; }</code></b> : la case suivante, différente, baisserait le drapeau, et seule la dernière case compterait. Un drapeau levé ne se baisse plus.</p>
<p>Pour <b>le premier qui…</b>, on garde sa position dans <code>$pos</code>, qui part de -1 (« pas trouvé »), et <code>break</code> arrête la boucle dès qu'on l'a.</p>`,
        example: '$pos = -1;\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($prenoms[$i] == $cherche) {\n        $pos = $i;\n        break;\n    }\n}\necho "Position : " . $pos;',
        vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Tom'], cherche: 'Tom' },
        tryit: 'Enlève le break : quelle position s\'affiche maintenant ?'
      },
      inarray: {
        title: 'in_array et array_search',
        html: `<p>PHP sait chercher tout seul :</p>
<ul><li><code>in_array($cherche, $prenoms)</code> vaut <code>true</code> si la valeur est dans la liste, <code>false</code> sinon ;</li><li><code>array_search($cherche, $prenoms)</code> donne le <b>numéro de la première case</b> qui la contient, ou <code>false</code> si elle n'y est pas.</li></ul>
<div class="rule">$pos = array_search('Léa', ['Léa', 'Tom']);  <span class="c">// 0</span><br><span class="kw">if</span> ($pos === <span class="kw">false</span>) { … }</div>
<p>Le piège : la première case porte le numéro <b>0</b>, et pour <code>if ($pos)</code> ou <code>$pos == false</code>, 0 ressemble à false. Compare toujours avec <code>=== false</code>.</p>`,
        example: 'if (in_array(\'Tom\', $prenoms)) {\n    echo "Tom est là\\n";\n}\n$pos = array_search(\'Léa\', $prenoms);\nif ($pos === false) {\n    echo "Pas de Léa";\n} else {\n    echo "Léa est en case " . $pos;\n}',
        vars: { prenoms: ['Léa', 'Tom', 'Inès'] },
        tryit: 'Remplace === false par == false : où PHP croit-il que Léa se trouve ?'
      }
    },
    steps: {
      predire: { before: 'drapeau', kind: 'choose', ask: 'Sans l\'exécuter : qu\'affiche ce programme ?', code: '$trouve = \'non\';\nforeach ([\'Léa\', \'Tom\', \'Inès\'] as $p) {\n    if ($p == \'Tom\') {\n        $trouve = \'oui\';\n    } else {\n        $trouve = \'non\';\n    }\n}\necho $trouve;', options: ['non', 'oui', 'oui non', 'Tom'], hints: ['Suis $trouve tour par tour : que lui arrive-t-il au tour d\'Inès, après Tom ?'] },
      suivre: { kind: 'trace', ask: 'Remplis le tableau de suivi : que valent $p et $trouve à la fin de chaque tour ?', code: '$trouve = false;\nforeach ($prenoms as $p) {\n    if ($p == $cherche) {\n        $trouve = true;\n    }\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], cherche: 'Tom' }, after: 5, watch: ['$p', '$trouve'], hints: ['Le drapeau passe à true au tour de Tom, et rien ne le remet à false ensuite.'] },
      comprendre: {},
      completer: { kind: 'complete', ask: 'Affiche le numéro de case du premier spécimen rangé en salle R4. S\'il n\'y en a aucun, affiche -1.', template: '$pos = [[]];\nfor ($i = 0; $i < count($salles); $i++) {\n    if ($salles[$i] == \'R4\' && $pos == -1) {\n        $pos = [[]];\n    }\n}\necho $pos;', fill: ['-1', '$i'], words: ['-1', '0', '$i', '$salles[$i]', 'true'], ref: '$pos = -1;\nfor ($i = 0; $i < count($salles); $i++) {\n    if ($salles[$i] == \'R4\' && $pos == -1) {\n        $pos = $i;\n    }\n}\necho $pos;', vars: { salles: ['R1', 'R4', 'R2', 'R4'] }, hidden: [{ vars: { salles: ['R4', 'R3'] }, label: 'R4 dans la première case' }, { vars: { salles: ['R1', 'R2'] }, label: 'aucune salle R4' }, { vars: { salles: ['R2', 'R5', 'R4'] }, label: 'R4 dans la dernière case' }], hints: ['-1 veut dire « pas encore trouvé » ; quand on trouve, on garde le numéro de case.', '$pos = -1;\n…\n        $pos = $i;'] },
      reparer: { kind: 'repair', ask: 'Ce programme doit afficher « Oui » si le prénom $cherche est dans la liste, sinon « Non ». Il répond « Non » alors qu\'Inès est bien là : répare-le.', starter: '$trouve = false;\nforeach ($prenoms as $p) {\n    if ($p == $cherche) {\n        $trouve = true;\n    } else {\n        $trouve = false;\n    }\n}\nif ($trouve) {\n    echo "Oui";\n} else {\n    echo "Non";\n}', ref: '$trouve = false;\nforeach ($prenoms as $p) {\n    if ($p == $cherche) {\n        $trouve = true;\n    }\n}\nif ($trouve) {\n    echo "Oui";\n} else {\n    echo "Non";\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], cherche: 'Inès' }, hidden: [{ vars: { cherche: 'Léa' }, label: 'le prénom est dans la première case' }, { vars: { cherche: 'Hugo' }, label: 'le prénom n\'est pas dans la liste' }, { vars: { cherche: 'Zoé' }, label: 'le prénom est dans la dernière case' }], traps: ['$trouve = false;\nfor ($i = 1; $i < count($prenoms); $i++) {\n    if ($prenoms[$i] == $cherche) {\n        $trouve = true;\n    }\n}\nif ($trouve) {\n    echo "Oui";\n} else {\n    echo "Non";\n}'], ir: [{ re: /else\s*\{\s*\$trouve\s*=\s*false/, text: 'Le <code>else</code> baisse le drapeau dès que la case suivante est différente : seule la dernière case compte. Un drapeau levé ne se baisse plus.' }, { re: /\$i\s*=\s*1\s*;/, text: 'La première case est la case 0 : avec <code>$i = 1</code>, elle n\'est jamais regardée.' }], hints: ['Suis $trouve avec « Pas à pas » : il passe à true au tour d\'Inès… et ensuite ?', '$trouve = false;\nforeach ($prenoms as $p) {\n    if ($p == $cherche) {\n        $trouve = true;\n    }\n}\n…'] },
      ecrire1: { before: 'inarray', kind: 'write', ask: 'Affiche « Présent » si l\'élève $cherche est dans la liste $prenoms, sinon « Absent ».', ref: 'if (in_array($cherche, $prenoms)) {\n    echo "Présent";\n} else {\n    echo "Absent";\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès'], cherche: 'Inès' }, hidden: [{ vars: { cherche: 'Léa' }, label: 'l\'élève est dans la première case' }, { vars: { cherche: 'Hugo' }, label: 'l\'élève n\'est pas dans la liste' }, { vars: { prenoms: [], cherche: 'Tom' }, label: 'une liste vide' }], traps: ['$trouve = false;\nforeach ($prenoms as $p) {\n    if ($p == $cherche) {\n        $trouve = true;\n    } else {\n        $trouve = false;\n    }\n}\nif ($trouve) {\n    echo "Présent";\n} else {\n    echo "Absent";\n}'], hints: ['in_array répond directement à la question « est-ce dans la liste ? ».', 'if (in_array($cherche, …)) {\n    echo "Présent";\n} else {\n    …\n}'] },
      ecrire2: { kind: 'write', ask: 'Affiche le premier spécimen qui vaut plus de 1000 €, avec son numéro de case : « Case 2 : 1200 ». S\'il n\'y en a aucun, affiche « Aucun ».', ref: '$pos = -1;\nfor ($i = 0; $i < count($valeurs); $i++) {\n    if ($valeurs[$i] > 1000) {\n        $pos = $i;\n        break;\n    }\n}\nif ($pos == -1) {\n    echo "Aucun";\n} else {\n    echo "Case " . $pos . " : " . $valeurs[$pos];\n}', vars: { valeurs: [450, 800, 1200, 300] }, hidden: [{ vars: { valeurs: [2500, 90, 1800] }, label: 'deux valeurs de plus de 1000 €, dont la première case' }, { vars: { valeurs: [1000, 700] }, label: 'pile 1000 € : ce n\'est pas plus de 1000' }], traps: ['$pos = -1;\nfor ($i = 0; $i < count($valeurs); $i++) {\n    if ($valeurs[$i] > 1000) {\n        $pos = $i;\n    }\n}\nif ($pos == -1) {\n    echo "Aucun";\n} else {\n    echo "Case " . $pos . " : " . $valeurs[$pos];\n}'], ir: [{ out: function (o) { return /^Case /.test(o); }, text: 'Sans <code>break</code> (ou sans tester <code>$pos == -1</code>), la boucle continue après la première trouvaille et garde la dernière.' }], hints: ['$pos part de -1 ; à la première valeur de plus de 1000, on garde $i et on sort de la boucle avec break.', '$pos = -1;\nfor ($i = 0; $i < count($valeurs); $i++) {\n    if ($valeurs[$i] > 1000) {\n        $pos = $i;\n        break;\n    }\n}\nif ($pos == -1) {\n    …\n}'] },
      ecrire3: { kind: 'write', ask: '$prenoms et $notes sont rangés dans le même ordre. Affiche « Inès : 15 » pour l\'élève $cherche. S\'il n\'est pas dans la liste, affiche « Inès : inconnu ».', ref: '$pos = array_search($cherche, $prenoms);\nif ($pos === false) {\n    echo $cherche . " : inconnu";\n} else {\n    echo $cherche . " : " . $notes[$pos];\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], notes: [14, 9, 15, 11], cherche: 'Inès' }, hidden: [{ vars: { cherche: 'Léa' }, label: 'l\'élève est dans la première case' }, { vars: { cherche: 'Hugo' }, label: 'l\'élève n\'est pas dans la liste' }], traps: ['$pos = array_search($cherche, $prenoms);\nif ($pos) {\n    echo $cherche . " : " . $notes[$pos];\n} else {\n    echo $cherche . " : inconnu";\n}', '$pos = array_search($cherche, $prenoms);\nif ($pos == false) {\n    echo $cherche . " : inconnu";\n} else {\n    echo $cherche . " : " . $notes[$pos];\n}'], ir: [{ re: /if\s*\(\s*\$pos\s*\)|\$pos\s*==\s*false/, text: '<code>array_search</code> renvoie 0 pour la première case, et 0 ressemble à false pour <code>if</code> et pour <code>==</code>. Compare avec <code>=== false</code>.' }], hints: ['array_search donne la case de l\'élève ; la même case de $notes donne sa note. Attention à la case 0.', '$pos = array_search($cherche, $prenoms);\nif ($pos === false) {\n    …\n} else {\n    echo $cherche . " : " . $notes[$pos];\n}'] },
      rappel1: { kind: 'recall' },
      rappel2: { kind: 'recall' }
    }
  });

  C.mastery({
    id: 'M12', chapter: 4, title: 'Totaliser, filtrer, chercher', covers: ['N28', 'N29', 'N30'], draw: 3,
    pool: [
      { ask: 'Affiche le total des absences de la liste $absences (0 si la liste est vide).', ref: '$total = 0;\nforeach ($absences as $a) {\n    $total = $total + $a;\n}\necho $total;', vars: { absences: [2, 0, 5, 1] }, hidden: [{ vars: { absences: [] }, label: 'une liste vide' }, { vars: { absences: [3] }, label: 'un seul élève' }], traps: ['$total = $absences[0];\nfor ($i = 1; $i < count($absences); $i++) {\n    $total = $total + $absences[$i];\n}\necho $total;'], hints: ['Un total à 0 avant la boucle, chaque tour y ajoute une case.', '$total = 0;\nforeach ($absences as $a) {\n    …\n}\necho $total;'] },
      { ask: 'Affiche la moyenne des notes arrondie à une décimale. S\'il n\'y a aucune note, affiche « Aucune note ».', ref: 'if (count($notes) == 0) {\n    echo "Aucune note";\n} else {\n    echo round(array_sum($notes) / count($notes), 1);\n}', vars: { notes: [12, 9, 16] }, hidden: [{ vars: { notes: [] }, label: 'aucune note' }, { vars: { notes: [7, 8] } }], traps: ['echo round(array_sum($notes) / count($notes), 1);'], hints: ['Teste la liste vide avant de diviser par count.', 'if (count($notes) == 0) {\n    …\n} else {\n    echo round(array_sum($notes) / count($notes), 1);\n}'] },
      { ask: 'La liste $altitudes donne l\'altitude, en mètres, des sites de fouille (négative sous la mer). Affiche la plus haute.', ref: '$max = $altitudes[0];\nforeach ($altitudes as $a) {\n    if ($a > $max) {\n        $max = $a;\n    }\n}\necho $max;', vars: { altitudes: [120, 45, 310, 80] }, hidden: [{ vars: { altitudes: [-12, -40, -7] }, label: 'tous les sites sous la mer' }, { vars: { altitudes: [-3] }, label: 'un seul site' }], traps: ['$max = 0;\nforeach ($altitudes as $a) {\n    if ($a > $max) {\n        $max = $a;\n    }\n}\necho $max;'], hints: ['Le maximum part de la première case, jamais de 0.', '$max = $altitudes[0];\nforeach ($altitudes as $a) {\n    …\n}\necho $max;'] },
      { ask: 'Affiche sur une ligne les notes d\'au moins 10, séparées par « , ». S\'il n\'y en a aucune, affiche « Aucune ».', ref: '$res = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        $res[] = $n;\n    }\n}\nif (count($res) == 0) {\n    echo "Aucune";\n} else {\n    echo implode(", ", $res);\n}', vars: { notes: [12, 7, 15, 9] }, hidden: [{ vars: { notes: [10, 3, 10] }, label: 'des notes pile à 10' }, { vars: { notes: [4, 8] }, label: 'aucune note d\'au moins 10' }], traps: ['$res = [];\nforeach ($notes as $n) {\n    if ($n > 10) {\n        $res[] = $n;\n    }\n}\nif (count($res) == 0) {\n    echo "Aucune";\n} else {\n    echo implode(", ", $res);\n}'], hints: ['Construis la liste des notes gardées, puis implode, ou « Aucune » si elle est vide.', '$res = [];\nforeach ($notes as $n) {\n    if ($n >= 10) {\n        …\n    }\n}\nif (count($res) == 0) {\n    …\n}'] },
      { ask: 'Affiche le nombre de spécimens qui valent plus de $seuil euros, puis la somme de leurs valeurs, une valeur par ligne.', ref: '$nb = 0;\n$somme = 0;\nforeach ($valeurs as $v) {\n    if ($v > $seuil) {\n        $nb++;\n        $somme = $somme + $v;\n    }\n}\necho $nb . "\\n";\necho $somme;', vars: { valeurs: [450, 1200, 800, 3000], seuil: 700 }, hidden: [{ vars: { valeurs: [700, 900], seuil: 700 }, label: 'une valeur pile égale au seuil' }, { vars: { seuil: 5000 }, label: 'aucune valeur au-dessus du seuil' }], traps: ['$nb = 0;\n$somme = 0;\nforeach ($valeurs as $v) {\n    if ($v >= $seuil) {\n        $nb++;\n        $somme = $somme + $v;\n    }\n}\necho $nb . "\\n";\necho $somme;'], hints: ['Un compteur et une somme, tous deux préparés avant la boucle ; un if pour ne prendre que les valeurs au-dessus du seuil.', '$nb = 0;\n$somme = 0;\nforeach ($valeurs as $v) {\n    if ($v > $seuil) {\n        …\n    }\n}\n…'] },
      { ask: 'Affiche « Oui » si la salle $cherche est dans la liste $salles, sinon « Non ».', ref: 'if (in_array($cherche, $salles)) {\n    echo "Oui";\n} else {\n    echo "Non";\n}', vars: { salles: ['R1', 'R3', 'R5'], cherche: 'R5' }, hidden: [{ vars: { cherche: 'R1' }, label: 'la salle est dans la première case' }, { vars: { cherche: 'R2' }, label: 'la salle n\'est pas dans la liste' }], traps: ['$trouve = false;\nforeach ($salles as $s) {\n    if ($s == $cherche) {\n        $trouve = true;\n    } else {\n        $trouve = false;\n    }\n}\nif ($trouve) {\n    echo "Oui";\n} else {\n    echo "Non";\n}'], hints: ['in_array, ou un drapeau sans else.', 'if (in_array($cherche, $salles)) {\n    …\n} else {\n    …\n}'] },
      { ask: 'Un 0 dans $notes est une copie blanche. Affiche le numéro de case de la première copie blanche, ou « Aucune ».', ref: '$pos = array_search(0, $notes);\nif ($pos === false) {\n    echo "Aucune";\n} else {\n    echo $pos;\n}', vars: { notes: [12, 0, 15, 9] }, hidden: [{ vars: { notes: [0, 11, 0] }, label: 'deux copies blanches, dont la première case' }, { vars: { notes: [14, 8] }, label: 'aucune copie blanche' }], traps: ['$pos = -1;\nfor ($i = 0; $i < count($notes); $i++) {\n    if ($notes[$i] == 0) {\n        $pos = $i;\n    }\n}\nif ($pos == -1) {\n    echo "Aucune";\n} else {\n    echo $pos;\n}', '$pos = array_search(0, $notes);\nif ($pos) {\n    echo $pos;\n} else {\n    echo "Aucune";\n}'], hints: ['array_search, comparé avec === false ; ou une boucle qui s\'arrête à la première trouvaille.', '$pos = array_search(0, $notes);\nif ($pos === false) {\n    …\n} else {\n    …\n}'] },
      { ask: '$prenoms et $notes sont rangés dans le même ordre. Affiche le prénom de l\'élève qui a la meilleure note. En cas d\'ex æquo, le premier dans la liste.', ref: '$best = 0;\nfor ($i = 1; $i < count($notes); $i++) {\n    if ($notes[$i] > $notes[$best]) {\n        $best = $i;\n    }\n}\necho $prenoms[$best];', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], notes: [14, 9, 17, 11] }, hidden: [{ vars: { notes: [16, 12, 16, 8] }, label: 'deux meilleures notes ex æquo' }, { vars: { prenoms: ['Hugo'], notes: [10] }, label: 'un seul élève' }], traps: ['$best = 0;\nfor ($i = 1; $i < count($notes); $i++) {\n    if ($notes[$i] >= $notes[$best]) {\n        $best = $i;\n    }\n}\necho $prenoms[$best];'], hints: ['Garde la position de la meilleure note plutôt que la note elle-même ; ne la remplace que si une note la dépasse vraiment.', '$best = 0;\nfor ($i = 1; $i < count($notes); $i++) {\n    if ($notes[$i] > $notes[$best]) {\n        …\n    }\n}\necho $prenoms[$best];'] },
      { ask: '$prenoms et $absences sont rangés dans le même ordre. Affiche, un par ligne, les prénoms des élèves qui ont au moins $min absences, ou « Personne ».', ref: '$liste = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($absences[$i] >= $min) {\n        $liste[] = $prenoms[$i];\n    }\n}\nif (count($liste) == 0) {\n    echo "Personne";\n} else {\n    foreach ($liste as $p) {\n        echo $p . "\\n";\n    }\n}', vars: { prenoms: ['Léa', 'Tom', 'Inès', 'Zoé'], absences: [1, 6, 0, 4], min: 3 }, hidden: [{ vars: { absences: [3, 2, 5, 0] }, label: 'Léa a pile 3 absences' }, { vars: { min: 10 }, label: 'personne n\'atteint le minimum' }], traps: ['$liste = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($absences[$i] > $min) {\n        $liste[] = $prenoms[$i];\n    }\n}\nif (count($liste) == 0) {\n    echo "Personne";\n} else {\n    foreach ($liste as $p) {\n        echo $p . "\\n";\n    }\n}'], hints: ['Une liste vide, une boucle for sur les deux listes, puis « Personne » ou une ligne par prénom.', '$liste = [];\nfor ($i = 0; $i < count($prenoms); $i++) {\n    if ($absences[$i] >= $min) {\n        …\n    }\n}\n…'] }
    ]
  });

